text:
{
  "title_novice": "Дельта: где и почему возникает",
  "summary": [
    {"text": "Дельта — конус из обломков, которые приносит река, там, где она достигает базиса эрозии.", "claims": ["c1"]},
    {"text": "Форма дельты зависит от взаимодействия речных и морских (озёрных) процессов и от других факторов.", "claims": ["c2", "c3"]}
  ],
  "claims": [
    {"key": "c1", "text": "Дельта — конус из обломков, который приносит река. Он образуется там, где река достигает базиса эрозии.", "kind": "observation", "unit_id": "u-030-1567ed", "page": 30, "quote": "Дельта — конус выноса обломочного материала, приносимого рекой, возникающий в месте достижения рекой базиса эрозии", "numbers": [], "question": null},
    {"key": "c2", "text": "Геометрия дельты определяется взаимодействием речных (флювиальных) и морских (озёрных) процессов и другими факторами.", "kind": "inference", "unit_id": "u-030-1567ed", "page": 30, "quote": "Геометрия дельт определяется, взаимодействием флювиальных, морских (озерных) процессов, а также другими факторами", "numbers": [], "question": null},
    {"key": "c3", "text": "Другие факторы: сток реки, климат, тектоника, рельеф, высота волн и приливные течения.", "kind": "inference", "unit_id": "u-030-1567ed", "page": 30, "quote": "величиной речного стока, климатом, характером и амплитудой тектонических движений, рельефом, высотой волн и приливных течений", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Река несёт обломочный материал. Там, где она достигает базиса эрозии, этот материал накапливается и образует конус.", "claims": ["c1"], "hypothesis": false},
    {"text": "В устье течение реки замедляется, и обломки оседают. Это общепринятое физическое объяснение, не из текста главы.", "claims": [], "hypothesis": true},
    {"text": "Базис эрозии — уровень, ниже которого река не может углубить своё русло.", "claims": [], "hypothesis": true},
    {"text": "Дельта образуется там, где речные процессы встречаются с морскими (озёрными).", "claims": ["c2"], "hypothesis": false},
    {"text": "Форма конуса зависит от этого взаимодействия и от других факторов.", "claims": ["c2"], "hypothesis": false},
    {"text": "Факторы, которые задают форму: сток реки, климат, тектоника, рельеф, высота волн и приливные течения.", "claims": ["c3"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Специалист сначала находит место, где река встречает базис эрозии: море или озеро.", "claims": [], "hypothesis": true},
    {"text": "Затем он оценивает, какие из факторов (сток, климат, тектоника, рельеф, волны, приливы) важны для данного места.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Список факторов не исчерпывающий: автор добавляет «а также другими факторами».", "claims": ["c2"], "hypothesis": false},
    {"text": "В тексте нет числовых порогов для факторов. Сказано только, что они влияют на форму.", "claims": ["c3"], "hypothesis": false},
    {"text": "Дельта может возникнуть и в озере, а не только в море: автор пишет «морских (озерных)».", "claims": ["c2"], "hypothesis": false},
    {"text": "Определение требует условия: река должна достигать базиса эрозии. Без него конуса по этому определению нет.", "claims": ["c1"], "hypothesis": false}
  ],
  "deeper": [],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Условие появления дельты: река достигает базиса эрозии.", "claims": ["c1"]},
    {"text": "Геометрия дельты зависит от взаимодействия речных и морских (озёрных) процессов.", "claims": ["c2"]},
    {"text": "Факторы формы: сток, климат, тектоника, рельеф, высота волн, приливные течения. Числовых порогов нет.", "claims": ["c3"]}
  ],
  "terms_defined": [
    {"term": "дельта", "term_en": "delta", "abbr": "", "definition": "Конус выноса обломочного материала, который приносит река в месте, где она достигает базиса эрозии.", "claims": ["c1"]},
    {"term": "базис эрозии", "term_en": "base level of erosion", "abbr": "", "definition": "Уровень, ниже которого река не может углубить своё русло.", "claims": ["c1"]},
    {"term": "конус выноса", "term_en": "alluvial cone", "abbr": "", "definition": "Конус из обломочного материала, вынесенного рекой.", "claims": ["c1"]},
    {"term": "флювиальные процессы", "term_en": "fluvial processes", "abbr": "", "definition": "Процессы, связанные с работой реки и её потоком.", "claims": ["c2"]},
    {"term": "обломочный материал", "term_en": "clastic material", "abbr": "", "definition": "Частицы горных пород, разрушенные и перенесённые водой.", "claims": ["c1"]},
    {"term": "речной сток", "term_en": "river discharge", "abbr": "", "definition": "Объём воды, который река проносит за единицу времени.", "claims": ["c3"]},
    {"term": "тектонические движения", "term_en": "tectonic movements", "abbr": "", "definition": "Медленные перемещения и деформации земной коры.", "claims": ["c3"]},
    {"term": "приливные течения", "term_en": "tidal currents", "abbr": "", "definition": "Течения, которые создаёт приливная волна: подъём и спад уровня моря.", "claims": ["c3"]}
  ],
