    "pack_id": null,
    "wrong": "Дельта — любое устье реки. Её форма везде одинакова, потому что её создаёт только река.",
    "right": "Дельта — конус обломков там, где река достигает базиса эрозии. Её форма зависит от речных и морских (озёрных) процессов и других факторов.",
    "claims": ["c1", "c2", "c3"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Сток реки, климат, тектоника, рельеф, высота волн и приливные течения — факторы формы.", "claims": ["c3"], "hypothesis": false},
      {"text": "Место, где река достигает базиса эрозии.", "claims": ["c1"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Конус обломочного материала — форма дельты.", "claims": ["c1"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Один фактор не задаёт форму: она зависит от взаимодействия процессов и других факторов.", "claims": ["c2"], "hypothesis": false},
      {"text": "Числовых порогов для факторов в тексте нет.", "claims": ["c3"], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Дельта как точка слияния потоков: много входящих потоков (вода, обломки) сходятся в одной точке, где они оседают и накапливаются.",
    "breaks_where": "Дельта — физическое тело, которое растёт годами и не похоже на очередь обработки данных. Форма зависит от сил природы, а не от логики конвейера.",
    "hypothesis": true
  },
